     }
 
     const atividadeId = req.params.id;
     const atividade = activityRepository.findAll().find((a) => a.id === atividadeId);
     if (!atividade) {
       res.status(404).json({ erro: 'NAO_ENCONTRADO', mensagem: 'Atividade não encontrada' });
       return;
     }
 
     const encontrosOrdenados = [...atividade.encontros].sort(
       (a, b) => DateTime.fromISO(a.inicio).toMillis() - DateTime.fromISO(b.inicio).toMillis()
     );
 
     const resultado = emitirCertificado.execute(
       { id: atividade.id, cargaHorariaMinutos: atividade.cargaHorariaMinutos, encontros: encontrosOrdenados },
       user.id
     );
 
     if (!resultado.ok) {
       const mensagem = resultado.erro === 'ATIVIDADE_NAO_ENCERRADA'
         ? 'A atividade ainda não foi encerrada'
         : 'Presença mínima de 75% não atingida';
       res.status(422).json({ erro: resultado.erro, mensagem });
       return;
     }
 
     res.status(201).json(resultado.certificado);
   });
 
   app.use((_req: Request, res: Response) => {
     res.status(404).json({ erro: 'NAO_ENCONTRADO', mensagem: 'Recurso não encontrado' });
   });
 
   app.use((err: any, _req: Request, res: Response, _next: NextFunction) => {
     if (err instanceof SyntaxError && 'body' in err) {
       res.status(422).json({ erro: 'DADOS_INVALIDOS', mensagem: 'JSON malformado' });
       return;
     }
     if (err instanceof ConflictError || err.code === 'CONFLITO_DE_SALA' || err.code === 'JA_INSCRITO' || err.code === 'CONFLITO_DE_HORARIO') {
       res.status(409).json({ erro: err.code || 'CONFLITO_DE_SALA', mensagem: err.message });
       return;
     }
     if (err instanceof DomainError) {
       if (err.code === 'NAO_INSCRITO') {
         res.status(403).json({ erro: err.code, mensagem: err.message });
         return;
       }
       res.status(422).json({ erro: err.code, mensagem: err.message });
       return;
     }
     if (err instanceof NotFoundError) {
       res.status(404).json({ erro: 'NAO_ENCONTRADO', mensagem: err.message });
       return;
     }
     res.status(422).json({ erro: 'DADOS_INVALIDOS', mensagem: err.message || 'Erro de validação' });
   });
 
   (app as any).close = () => {
     db.close();
   };
 
   return app;
 }
